   879  PrefixTlv *NetworkData::FindPrefix(const uint8_t *aPrefix, uint8_t aPrefixLength, uint8_t *aTlvs, uint8_t aTlvsLength)
   880  {
   881      NetworkDataTlv *cur     = reinterpret_cast<NetworkDataTlv *>(aTlvs);
   882      NetworkDataTlv *end     = reinterpret_cast<NetworkDataTlv *>(aTlvs + aTlvsLength);
   883      PrefixTlv *     compare = NULL;
   884
   885      while (cur < end)
   886      {
   887          VerifyOrExit((cur + 1) <= end && cur->GetNext() <= end);
   888
   889          if (cur->GetType() == NetworkDataTlv::kTypePrefix)
   890          {
   891              compare = reinterpret_cast<PrefixTlv *>(cur);
   892
   893              if (compare->GetPrefixLength() == aPrefixLength &&
   894                  PrefixMatch(compare->GetPrefix(), aPrefix, aPrefixLength) >= aPrefixLength)
   895              {
   896                  ExitNow();
   897              }
   898          }
   899
   900          cur = cur->GetNext();
   901      }
   902
   903      compare = NULL;
   904
   905  exit:
   906      return compare;
   907  }
